$ErrorActionPreference='Stop';$base='http://192.168.122.1:8872';$root='C:\JudasValidation';Invoke-WebRequest -UseBasicParsing "$base/m73-expected-source.json" -OutFile "$root\m73-expected-source.json";$expected=Get-Content "$root\m73-expected-source.json" -Raw|ConvertFrom-Json;$results=@();foreach($p in $expected.PSObject.Properties){$actual=(Get-FileHash (Join-Path "$root\Source" $p.Name) -Algorithm SHA256).Hash.ToLower();$results+=@{path=$p.Name;expected=$p.Value;actual=$actual;matches=($p.Value -eq $actual)}};$results|ConvertTo-Json -Depth 4|Set-Content "$root\m73-final-source-proof.json" -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/m73-final-source-proof.json" -Method Post -InFile "$root\m73-final-source-proof.json"|Out-Null;if($results.Where({!$_.matches}).Count){throw 'Source hash mismatch'};Write-Output "SOURCE $($results.Count) files match"